python3 - <<'PYEOF'
p = '/Users/guillaumeloulier/PhpstormProjects/oss/elephc/.claude/worktrees/streams-csv-signature/src/types/checker/functions/resolution/signature.rs'
s = open(p).read()
s = s.replace(
    """/// The honest type is the UNION of what the caller had and what the body leaves: the callee may
/// write on one path and not another, so `null` stays reachable. A union is boxed storage, which
/// is also what makes the writeback representable — the caller boxes its null into a Mixed cell,
/// hands over the cell's address, and unboxes it back afterwards.""",
    """/// The widened type is `mixed`, not the narrower `<written>|null` union it might look like it
/// should be. Both are boxed, but a nullable SCALAR union has its own inline representation — a
/// payload word plus a tag word, sixteen bytes — while the caller's slot was laid out for the
/// eight-byte null it was holding, so the callee's write ran past the end of it and the program
/// segfaulted. `mixed` is one pointer whatever the payload, which is the only representation
/// both sides of the boundary agree on here.""",
)
s = s.replace(
    "    Some(PhpType::Union(vec![exit_ty.clone(), PhpType::Void]))",
    "    Some(PhpType::Mixed)",
)
open(p, 'w').write(s)
print("widened type is now Mixed")
